  questions = '[{"prompt": "Complete: In the Northeast, the smell of acarajé frying in palm oil reminds people of their roots, while in the South, the ritual of drinking chimarrão is a social act that promotes ___ and bonding.", "options": ["conversation", "Brazil", "food", "much"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Sharing a meal is a universal language that brings people together, bridging ___ gaps and creating memories that last a lifetime.", "options": ["Brazil", "generational", "food", "much"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Whether it is through a ___ potluck or a simple dinner with friends, these moments are vital for our well-being.", "options": ["Brazil", "food", "neighborhood", "much"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: By preserving our culinary traditions and supporting our local food systems, we strengthen the ties that bind us and ensure that our ___ continue to thrive for years to come.", "options": ["Brazil", "food", "communities", "much"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: These markets are the backbone of local economies, supporting small producers and ___ a more sustainable way of living that prioritizes quality and direct contact.", "options": ["Brazil", "food", "much", "encouraging"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: These traditions are passed down through ___, ensuring that cultural heritage remains alive in a rapidly changing world.", "options": ["generations", "Brazil", "food", "much"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}]'::jsonb
