  questions = '[{"prompt": "Complete: With discounts and ___ constantly appearing on our screens, it is easy to spend money on things we do not really need.", "options": ["Financial", "literacy", "advertisements", "essential"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Having this safety net provides peace of mind and prevents people from falling into debt when faced with unforeseen ___ that might arise at any moment.", "options": ["Financial", "literacy", "circumstances", "essential"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: In the end, financial health is about ___ and discipline.", "options": ["Financial", "consistency", "literacy", "essential"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Creating a budget is the first step toward financial stability, allowing individuals to ___ between their needs and their wants.", "options": ["Financial", "literacy", "distinguish", "essential"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Many Brazilians are learning that managing money is not just about earning a salary, but about how ___ that money is tracked and allocated.", "options": ["Financial", "literacy", "essential", "effectively"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Creating a budget is the first step toward financial stability, allowing ___ to distinguish between their needs and their wants.", "options": ["individuals", "Financial", "literacy", "essential"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}]'::jsonb
