  questions = '[{"prompt": "Complete: This flexibility allows adults to balance their studies with work and family ___, making it possible to learn at their own pace from the comfort of home.", "options": ["responsibilities", "rapidly", "changing", "world"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: When we stop believing that we know everything, we open the door to endless ___ for improvement and discovery throughout our lives.", "options": ["rapidly", "changing", "opportunities", "world"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: The concept of lifelong learning has become ___ important, as new technologies and industries emerge at a fast pace.", "options": ["rapidly", "changing", "increasingly", "world"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Engaging with new ideas and challenging our ___ keeps the mind sharp and curious.", "options": ["rapidly", "changing", "world", "perspectives"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Lifelong learning is not just about ___ advancement; it is also about personal growth.", "options": ["professional", "rapidly", "changing", "world"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: The concept of lifelong learning has become increasingly important, as new ___ and industries emerge at a fast pace.", "options": ["rapidly", "technologies", "changing", "world"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}]'::jsonb
