  questions = '[{"prompt": "Complete: By front-loading the most mentally demanding work, individuals create a sense of accomplishment that permeates the rest of their day, reducing the anxiety often associated with ___.", "options": ["unpredictability", "fast", "paced", "society"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: By front-loading the most mentally demanding work, individuals create a sense of ___ that permeates the rest of their day, reducing the anxiety often associated with unpredictability.", "options": ["fast", "paced", "society", "accomplishment"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Negotiating boundaries with colleagues, saying no to non-essential commitments, and delegating tasks effectively are all ___ of a mature, autonomous lifestyle.", "options": ["manifestations", "fast", "paced", "society"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: By taking ___ for our daily habits, we transform from passive participants in our lives into architects of our own destiny.", "options": ["fast", "responsibility", "paced", "society"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: It is a delicate dance between self-reliance and the ___ nature of our professional environments, requiring one to be assertive without appearing uncooperative.", "options": ["fast", "collaborative", "paced", "society"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Many professionals find that maintaining independence requires sophisticated ___ skills.", "options": ["fast", "paced", "communication", "society"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: This intentional ___ is a powerful form of modern independence, protecting the individual from the relentless demands of the attention economy.", "options": ["fast", "paced", "society", "disconnection"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: This shift requires a disciplined approach to time management, where the boundaries between productivity and rest are ___ established to prevent burnout.", "options": ["intentionally", "fast", "paced", "society"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}]'::jsonb
