  questions = '[{"prompt": "Complete: In un''epoca segnata ___, ritrovare il senso del collettivo è un antidoto potente contro la frammentazione della società moderna.", "options": ["panorama", "contemporaneo", "relazioni", "dall''individualismo"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: In conclusione, costruire relazioni solide richiede ___ e intenzione.", "options": ["panorama", "contemporaneo", "relazioni", "consapevolezza"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: In un''epoca segnata dall''individualismo, ritrovare il senso del collettivo è un antidoto potente contro la ___ della società moderna.", "options": ["frammentazione", "panorama", "contemporaneo", "relazioni"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: La ___ a comunità, associazioni o gruppi di interesse rappresenta un pilastro fondamentale per il benessere psicologico.", "options": ["panorama", "partecipazione", "contemporaneo", "relazioni"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: In un mondo che cambia, la capacità di prendersi cura degli altri rimane la competenza umana più preziosa e, forse, la più ___ di tutte.", "options": ["panorama", "contemporaneo", "rivoluzionaria", "relazioni"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Nel panorama contemporaneo, le relazioni sociali stanno attraversando una fase di profonda ___, segnata da una fluidità che un tempo era sconosciuta.", "options": ["panorama", "contemporaneo", "relazioni", "trasformazione"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Nel panorama contemporaneo, le relazioni sociali stanno ___ una fase di profonda trasformazione, segnata da una fluidità che un tempo era sconosciuta.", "options": ["panorama", "contemporaneo", "relazioni", "attraversando"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: La ___ mediata dallo schermo spesso manca di quella componente non verbale che è fondamentale per costruire una vera empatia.", "options": ["comunicazione", "panorama", "contemporaneo", "relazioni"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}]'::jsonb
