  questions = '[{"prompt": "Complete: Oltre al risparmio, il tema ___ è sempre più attuale.", "options": ["gestione", "dell''investimento", "delle", "finanze"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: La ___ finanziaria è, in sostanza, una forma di libertà che permette di fare scelte basate sui valori personali piuttosto che sulla necessità immediata.", "options": ["gestione", "delle", "finanze", "consapevolezza"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Questo ''cuscinetto'' finanziario permette di affrontare periodi di ___, spese mediche improvvise o riparazioni domestiche senza dover ricorrere a prestiti ad alto interesse, che rappresentano una trappola per molti consumatori.", "options": ["disoccupazione", "gestione", "delle", "finanze"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: L''obiettivo finale non è l''accumulo di ricchezza fine a se stesso, ma ___ di una serenità che permetta di vivere in linea con le proprie aspirazioni.", "options": ["gestione", "l''acquisizione", "delle", "finanze"], "answer_index": 1, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: L''educazione finanziaria, in questo senso, è ___ più redditizio che una persona possa fare su se stessa.", "options": ["gestione", "delle", "l''investimento", "finanze"], "answer_index": 2, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Molte persone vedono il budget come una restrizione, mentre in realtà è uno strumento di ___ che dà potere decisionale.", "options": ["gestione", "delle", "finanze", "pianificazione"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Siamo ___ bombardati da messaggi pubblicitari che ci spingono all''acquisto compulsivo per soddisfare desideri immediati.", "options": ["gestione", "delle", "finanze", "costantemente"], "answer_index": 3, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}, {"prompt": "Complete: Non si tratta di cercare guadagni facili o speculazioni rischiose, ma di pianificare una crescita graduale attraverso strumenti ___.", "options": ["diversificati", "gestione", "delle", "finanze"], "answer_index": 0, "explanation_pt_br": "Complete com a palavra que aparece no texto da leitura."}]'::jsonb
